SET DEFINE OFF;
SET SERVEROUTPUT ON SIZE UNLIMITED;
ALTER SESSION SET NLS_NUMERIC_CHARACTERS = '.,';
ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD HH24:MI:SS';
ALTER SESSION SET NLS_TIMESTAMP_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF3';

PROMPT =============================================================================
PROMPT INICIANDO INSTALACION DEL PROYECTO SITRA-ORO EN ESQUEMA ACTUAL
PROMPT =============================================================================

-- -----------------------------------------------------------------------------
-- 1. LIMPIEZA SEGURA DE ESTRUCTURAS PREVIAS
-- -----------------------------------------------------------------------------
PROMPT [1/6] Limpiando tablas, restricciones y secuencias previas...
BEGIN
   FOR cur_rec IN (SELECT table_name FROM user_tables) LOOP
      BEGIN
         EXECUTE IMMEDIATE 'DROP TABLE "' || cur_rec.table_name || '" CASCADE CONSTRAINTS PURGE';
      EXCEPTION
         WHEN OTHERS THEN NULL;
      END;
   END LOOP;
   FOR cur_seq IN (SELECT sequence_name FROM user_sequences WHERE sequence_name NOT LIKE 'ISEQ$$%') LOOP
      BEGIN
         EXECUTE IMMEDIATE 'DROP SEQUENCE "' || cur_seq.sequence_name || '"';
      EXCEPTION
         WHEN OTHERS THEN NULL;
      END;
   END LOOP;
END;
/

-- -----------------------------------------------------------------------------
-- 2. SECUENCIAS MANUALES DEL DOMINIO
-- -----------------------------------------------------------------------------
PROMPT [2/6] Creando secuencias manuales...
CREATE SEQUENCE SEQ_PONDERACION START WITH 100 INCREMENT BY 1 NOCACHE;
CREATE SEQUENCE SEQ_SOL_ENTREGA START WITH 100 INCREMENT BY 1 NOCACHE;

-- -----------------------------------------------------------------------------
-- 3. TABLAS Y PARTICIONAMIENTO NATIVO (RANGE, LIST Y HASH)
-- -----------------------------------------------------------------------------
PROMPT [3/6] Creando las 22 tablas y segmentos particionados...
CREATE TABLE PARAMETROS_SISTEMA (
    ID_PARAMETRO            NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    FECHA                   DATE DEFAULT SYSDATE NOT NULL,
    PRECIO_DIARIO_GRAMO_PEN NUMBER(10, 2) NOT NULL,
    PORCENTAJE_MERMA_EST    NUMBER(5, 2) DEFAULT 5.00 NOT NULL,
    COTIZACION_ONZA_USD     NUMBER(10, 2),
    TIPO_CAMBIO_USD_PEN     NUMBER(6, 4),
    ESTADO                  VARCHAR2(10) DEFAULT 'ACTIVO' CHECK (ESTADO IN ('ACTIVO', 'INACTIVO'))
);

CREATE TABLE ZONAS_ACOPIO (
    ID_ZONA                 NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NOMBRE                  VARCHAR2(100) NOT NULL,
    CONSTRAINT UK_ZONAS_ACOPIO_NOMBRE UNIQUE (NOMBRE)
);

CREATE TABLE MINEROS (
    ID_MINERO               NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    DOCUMENTO_IDENTIDAD     VARCHAR2(15) NOT NULL UNIQUE,
    NOMBRES_APELLIDOS       VARCHAR2(150) NOT NULL,
    TELEFONO                VARCHAR2(20),
    ZONA_PROCEDENCIA        VARCHAR2(100),
    FECHA_REGISTRO          TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    ID_CENTRO_ACOPIO        NUMBER(19, 0)
)
PARTITION BY HASH (ID_MINERO)
PARTITIONS 4;

CREATE TABLE CUENTAS_ACCESO (
    ID_CUENTA                   NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    DOCUMENTO_IDENTIDAD        VARCHAR2(15) NOT NULL UNIQUE,
    CLAVE_HASH                  VARCHAR2(100) NOT NULL,
    ROL                         VARCHAR2(20) NOT NULL,
    ID_MINERO                   NUMBER,
    ID_CENTRO_ACOPIO_PREFERIDO NUMBER,
    ID_CENTRO_ACOPIO_ASIGNADO  NUMBER,
    ACTIVO                      NUMBER(1) DEFAULT 1 NOT NULL,
    FECHA_CREACION              TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT CK_CUENTAS_ROL CHECK (ROL IN ('MINERO', 'G2_ACOPIADOR', 'G1_MAYORISTA')),
    CONSTRAINT CK_CUENTAS_ACTIVO CHECK (ACTIVO IN (0, 1))
);

CREATE TABLE CENTROS_ACOPIO (
    ID_CENTRO_ACOPIO       NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NOMBRE                 VARCHAR2(120) NOT NULL,
    ZONA                   VARCHAR2(100) NOT NULL,
    DIRECCION              VARCHAR2(200) NOT NULL,
    TELEFONO               VARCHAR2(20),
    ID_CUENTA_ACOPIADOR    NUMBER NOT NULL UNIQUE,
    ACTIVO                 NUMBER(1) DEFAULT 1 NOT NULL,
    CONSTRAINT UK_CENTRO_NOMBRE_ZONA UNIQUE (NOMBRE, ZONA),
    CONSTRAINT CK_CENTRO_ACTIVO CHECK (ACTIVO IN (0, 1))
)
PARTITION BY LIST (ZONA) (
    PARTITION P_ZONA_RINCONADA VALUES ('La Rinconada'),
    PARTITION P_ZONA_ANANEA    VALUES ('Ananea'),
    PARTITION P_ZONA_LUNAR     VALUES ('Lunar de Oro'),
    PARTITION P_ZONA_OTROS     VALUES (DEFAULT)
);

CREATE TABLE LEYES_ORO (
    ID_LEY NUMBER(19) PRIMARY KEY,
    VALOR NUMBER(7,4) NOT NULL CONSTRAINT UQ_LEY_VALOR UNIQUE,
    CONSTRAINT CK_LEY_VALOR CHECK (VALOR > 0 AND VALOR <= 100),
    CONSTRAINT CK_LEY_ID CHECK (ID_LEY = VALOR * 10000)
);

CREATE TABLE COTIZACIONES_COLOR (
    ID_COTIZACION NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    COLOR VARCHAR2(5) NOT NULL CHECK (COLOR IN ('ROJO','VERDE')),
    ONZA_USD NUMBER(12,2) NOT NULL CHECK (ONZA_USD > 0),
    DOLAR_PEN NUMBER(10,4) NOT NULL CHECK (DOLAR_PEN > 0),
    EXPORTACION_PCT NUMBER(7,4) NOT NULL CHECK (EXPORTACION_PCT BETWEEN 0 AND 100),
    PRECIO_GRAMO_PEN NUMBER(16,2) NOT NULL CHECK (PRECIO_GRAMO_PEN >= 0),
    FECHA_PUBLICACION TIMESTAMP NOT NULL,
    LEY_PCT NUMBER(7,4) NOT NULL
);

CREATE TABLE LIQUIDACIONES_G1 (
    ID_LIQUIDACION_G1       NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    NOMBRE_ACOPIADOR_G2     VARCHAR2(150) NOT NULL,
    ESTADO                  VARCHAR2(20) DEFAULT 'REGISTRADA' NOT NULL
                            CONSTRAINT CK_LIQ_G1_ESTADO CHECK (ESTADO IN ('REGISTRADA', 'ANULADA')),
    PESO_TOTAL_FUNDIDO_G    NUMBER(10, 3) NOT NULL,
    TIPO_ORO                VARCHAR2(12)
                            CONSTRAINT CK_LIQ_G1_TIPO_ORO CHECK (TIPO_ORO IN ('ROJO', 'VERDE', 'CONSOLIDADO')),
    COTIZACION_ONZA_USD     NUMBER(10, 2) NOT NULL,
    TIPO_CAMBIO_USD_PEN     NUMBER(6, 4) NOT NULL,
    PRECIO_RESULTANTE_GRAMO NUMBER(10, 2),
    TOTAL_PAGADO_G2_PEN     NUMBER(12, 2) NOT NULL,
    FECHA_LIQUIDACION       TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    ID_CENTRO_ACOPIO        NUMBER
)
PARTITION BY RANGE (FECHA_LIQUIDACION)
INTERVAL (NUMTOYMINTERVAL(1, 'MONTH')) (
    PARTITION P_LIQ_HISTORICO VALUES LESS THAN (TIMESTAMP '2026-01-01 00:00:00')
);

CREATE TABLE DETALLE_LIQUIDACIONES_G1 (
    ID_DETALLE_LIQUIDACION  NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_LIQUIDACION_G1       NUMBER NOT NULL,
    TIPO_ORO                VARCHAR2(10) NOT NULL
                            CONSTRAINT CK_DET_LIQ_G1_TIPO CHECK (TIPO_ORO IN ('ROJO', 'VERDE')),
    PESO_FUNDIDO_G          NUMBER(10, 3) NOT NULL,
    PRECIO_GRAMO_PEN        NUMBER(10, 2) NOT NULL,
    SUBTOTAL_PEN            NUMBER(12, 2) NOT NULL,
    CONSTRAINT UQ_DET_LIQ_G1_COLOR UNIQUE (ID_LIQUIDACION_G1, TIPO_ORO)
);

CREATE TABLE MAYORISTA_RECEPCIONES (
    ID_RECEPCION               NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    FECHA                      DATE NOT NULL,
    ID_CENTRO_ACOPIO            NUMBER NULL,
    NOMBRE_ACOPIADOR            VARCHAR2(223 CHAR) NOT NULL,
    ROJO_PESO_SIN_FUNDIR_G      NUMBER(10,3),
    ROJO_PESO_FUNDIDO_G         NUMBER(10,3),
    ROJO_ONZA                   VARCHAR2(80),
    ROJO_DOLAR                  VARCHAR2(80),
    ROJO_EXPORTACION            VARCHAR2(80),
    ROJO_PAGO_MATERIAL          VARCHAR2(80),
    VERDE_PESO_SIN_FUNDIR_G     NUMBER(10,3),
    VERDE_PESO_FUNDIDO_G        NUMBER(10,3),
    VERDE_ONZA                  VARCHAR2(80),
    VERDE_DOLAR                 VARCHAR2(80),
    VERDE_EXPORTACION           VARCHAR2(80),
    VERDE_PAGO_MATERIAL         VARCHAR2(80),
    DESCUENTO                   VARCHAR2(100),
    TOTAL                       VARCHAR2(100),
    FECHA_CREACION              TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    REVISION_LEY                NUMBER(19) DEFAULT 0 NOT NULL,
    ID_MINERO_DIRECTO           NUMBER NULL,
    COMPRA_DIRECTA              NUMBER(1,0) DEFAULT 0 NOT NULL,
    CONSTRAINT CK_MAY_REC_ROJO_PESOS CHECK (
        (ROJO_PESO_SIN_FUNDIR_G IS NULL OR ROJO_PESO_SIN_FUNDIR_G >= 0)
        AND (ROJO_PESO_FUNDIDO_G IS NULL OR ROJO_PESO_FUNDIDO_G >= 0)
        AND (ROJO_PESO_FUNDIDO_G IS NULL OR ROJO_PESO_SIN_FUNDIR_G IS NOT NULL)
    ),
    CONSTRAINT CK_MAY_REC_VERDE_PESOS CHECK (
        (VERDE_PESO_SIN_FUNDIR_G IS NULL OR VERDE_PESO_SIN_FUNDIR_G >= 0)
        AND (VERDE_PESO_FUNDIDO_G IS NULL OR VERDE_PESO_FUNDIDO_G >= 0)
        AND (VERDE_PESO_FUNDIDO_G IS NULL OR VERDE_PESO_SIN_FUNDIR_G IS NOT NULL)
    ),
    CONSTRAINT CK_MAY_REC_CON_PESO CHECK (
        COMPRA_DIRECTA = 1 OR
        ROJO_PESO_SIN_FUNDIR_G IS NOT NULL OR VERDE_PESO_SIN_FUNDIR_G IS NOT NULL OR
        ROJO_PESO_FUNDIDO_G IS NOT NULL OR VERDE_PESO_FUNDIDO_G IS NOT NULL
    )
);

CREATE TABLE COMPRAS_G2 (
    ID_COMPRA_G2 NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_MINERO NUMBER NOT NULL,
    ID_CENTRO_ACOPIO NUMBER NOT NULL,
    FECHA_COMPRA TIMESTAMP NOT NULL
)
PARTITION BY RANGE (FECHA_COMPRA)
SUBPARTITION BY HASH (ID_MINERO) SUBPARTITIONS 2 (
    PARTITION P_COMPRAS_2026_S1 VALUES LESS THAN (TIMESTAMP '2026-07-01 00:00:00'),
    PARTITION P_COMPRAS_2026_S2 VALUES LESS THAN (TIMESTAMP '2027-01-01 00:00:00'),
    PARTITION P_COMPRAS_FUTURO  VALUES LESS THAN (MAXVALUE)
);

CREATE TABLE AJUSTES_COMPRA_G2 (
    ID_AJUSTE NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_TRANSACCION_G2 NUMBER NOT NULL,
    ID_CENTRO_ACOPIO NUMBER NOT NULL,
    ID_MINERO NUMBER NOT NULL,
    ID_RECEPCION_MAYORISTA NUMBER,
    ID_LIQUIDACION_G1 NUMBER,
    TIPO VARCHAR2(12) NOT NULL,
    ESTADO VARCHAR2(24) NOT NULL,
    MOTIVO VARCHAR2(500) NOT NULL,
    TIPO_ORO_ANTERIOR VARCHAR2(10) NOT NULL,
    PESO_SIN_FUNDIR_ANTERIOR NUMBER(10,3) NOT NULL,
    PESO_FUNDIDO_ANTERIOR NUMBER(10,3) NOT NULL,
    PRECIO_ANTERIOR NUMBER(10,2) NOT NULL,
    TOTAL_ANTERIOR NUMBER(12,2) NOT NULL,
    TIPO_ORO_NUEVO VARCHAR2(10),
    PESO_SIN_FUNDIR_NUEVO NUMBER(10,3),
    PESO_FUNDIDO_NUEVO NUMBER(10,3),
    PRECIO_NUEVO NUMBER(10,2),
    TOTAL_NUEVO NUMBER(12,2),
    SOLICITADO_POR VARCHAR2(40) NOT NULL,
    FECHA_SOLICITUD TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    FECHA_DECISION_MINERO TIMESTAMP,
    DECIDIDO_POR_MINERO VARCHAR2(40),
    FECHA_DECISION_MAYORISTA TIMESTAMP,
    DECIDIDO_POR_MAYORISTA VARCHAR2(40),
    CONSTRAINT CK_AJUSTE_G2_TIPO CHECK (TIPO IN ('EDICION', 'ANULACION')),
    CONSTRAINT CK_AJUSTE_G2_ESTADO CHECK (ESTADO IN
        ('PENDIENTE_MINERO', 'PENDIENTE_MAYORISTA', 'APROBADO', 'RECHAZADO_MINERO', 'RECHAZADO_MAYORISTA'))
);

CREATE TABLE TRANSACCIONES_G2 (
    ID_TRANSACCION_G2       NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_MINERO               NUMBER NOT NULL,
    PESO_SIN_FUNDIR_G       NUMBER(10, 3) NOT NULL,
    PESO_FUNDIDO_NETO_G     NUMBER(10, 3) NOT NULL,
    TIPO_ORO                VARCHAR2(10) NOT NULL CHECK (TIPO_ORO IN ('ROJO', 'VERDE')),
    PRECIO_APLICADO_PEN     NUMBER(10, 2) NOT NULL,
    TOTAL_PAGADO_PEN        NUMBER(12, 2) NOT NULL,
    FECHA_TRANSACCION       TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    ID_LIQUIDACION_G1       NUMBER NULL,
    ID_CENTRO_ACOPIO        NUMBER NOT NULL,
    ID_RECEPCION_MAYORISTA  NUMBER NULL,
    ANULADA                 NUMBER(1) DEFAULT 0 NOT NULL,
    ID_COMPRA_G2            NUMBER NULL,
    CONSTRAINT CK_G2_ANULADA CHECK (ANULADA IN (0, 1))
)
PARTITION BY RANGE (FECHA_TRANSACCION) (
    PARTITION P_TRANS_HISTORICO VALUES LESS THAN (TIMESTAMP '2026-01-01 00:00:00'),
    PARTITION P_TRANS_2026_Q1   VALUES LESS THAN (TIMESTAMP '2026-04-01 00:00:00'),
    PARTITION P_TRANS_2026_Q2   VALUES LESS THAN (TIMESTAMP '2026-07-01 00:00:00'),
    PARTITION P_TRANS_2026_Q3   VALUES LESS THAN (TIMESTAMP '2026-10-01 00:00:00'),
    PARTITION P_TRANS_2026_Q4   VALUES LESS THAN (TIMESTAMP '2027-01-01 00:00:00'),
    PARTITION P_TRANS_FUTURO    VALUES LESS THAN (MAXVALUE)
);

CREATE TABLE LOTES_EXPORTACION (
    ID_LOTE NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    FECHA DATE NOT NULL,
    ESTADO VARCHAR2(20 CHAR) DEFAULT 'BORRADOR' NOT NULL,
    FECHA_CREACION TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    FECHA_PREPARACION TIMESTAMP,
    CONSTRAINT CK_LOTE_EXP_ESTADO CHECK (ESTADO IN ('BORRADOR', 'PREPARADO'))
);

CREATE TABLE LOTE_EXPORTACION_PARTIDAS (
    ID_PARTIDA NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_LOTE NUMBER NOT NULL,
    ID_LIQUIDACION_G1 NUMBER NOT NULL,
    LECTURA_DECIMAL NUMBER(12,6) NOT NULL,
    CONSTRAINT UQ_LOTE_PART_LIQ UNIQUE (ID_LIQUIDACION_G1),
    CONSTRAINT CK_LOTE_PART_LECTURA CHECK (LECTURA_DECIMAL >= 0)
);

CREATE TABLE LOTE_RECEPCIONES (
    ID_RECEPCION NUMBER PRIMARY KEY,
    ID_LOTE NUMBER NOT NULL,
    PESO_ROJO_G NUMBER(10,3) NOT NULL CHECK (PESO_ROJO_G >= 0),
    PESO_VERDE_G NUMBER(10,3) NOT NULL CHECK (PESO_VERDE_G >= 0),
    PESO_FUNDIDO_G NUMBER(14,3)
);

CREATE TABLE RECEPCION_ACUMULADA (
    ID_ORIGEN NUMBER(19) PRIMARY KEY,
    ID_ACUMULADA NUMBER(19) NOT NULL,
    CONSTRAINT CK_RAC_DISTINTA CHECK (ID_ORIGEN <> ID_ACUMULADA)
);

CREATE TABLE RECEPCION_LEYES (
    ID_DETALLE NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ID_RECEPCION NUMBER NOT NULL,
    ID_LEY NUMBER(19) NOT NULL,
    ONZA_USD NUMBER(14,4) NOT NULL CHECK (ONZA_USD > 0),
    PORCENTAJE NUMBER(7,4) NOT NULL CHECK (PORCENTAJE >= 0 AND PORCENTAJE < 100),
    TIPO_CAMBIO NUMBER(10,4) NOT NULL CHECK (TIPO_CAMBIO > 0),
    PESO_SIN_FUNDIR_G NUMBER(10,3) NOT NULL CHECK (PESO_SIN_FUNDIR_G > 0),
    PESO_FUNDIDO_G NUMBER(10,3) NOT NULL CHECK (PESO_FUNDIDO_G > 0),
    PRECIO_USD NUMBER(18,2) NOT NULL,
    PRECIO_PEN NUMBER(18,2) NOT NULL CHECK (PRECIO_PEN > 0),
    TOTAL_PEN NUMBER(24,2) NOT NULL,
    CONSTRAINT CK_RLEY_PESOS CHECK (PESO_FUNDIDO_G <= PESO_SIN_FUNDIR_G),
    CONSTRAINT UQ_RECEPCION_LEY UNIQUE (ID_RECEPCION, ID_LEY)
);

CREATE TABLE REG_PONDERACION (
    ID_REGISTRO NUMBER PRIMARY KEY,
    FECHA TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    PESO_TOTAL NUMBER(18,3) NOT NULL,
    LECTURA NUMBER(10,7) NOT NULL,
    FUNDIDO NUMBER(18,3),
    CHECK (PESO_TOTAL > 0 AND LECTURA > 0 AND LECTURA <= 1),
    CHECK (FUNDIDO IS NULL OR (FUNDIDO >= 0 AND FUNDIDO <= PESO_TOTAL))
);

CREATE TABLE REG_PONDERACION_LEY (
    ID_REGISTRO NUMBER NOT NULL,
    NUMERO NUMBER NOT NULL,
    ID_LEY NUMBER NOT NULL,
    PESO NUMBER(10,3) NOT NULL CHECK (PESO > 0),
    PRIMARY KEY(ID_REGISTRO, NUMERO)
);

CREATE TABLE SOL_ENTREGA_MINERO (
    ID_SOLICITUD NUMBER PRIMARY KEY,
    ID_MINERO NUMBER NOT NULL,
    ID_CENTRO_ACOPIO NUMBER NOT NULL,
    ESTADO VARCHAR2(20) DEFAULT 'PENDIENTE' NOT NULL CHECK (ESTADO IN ('PENDIENTE','ACEPTADA','COMPRA_REGISTRADA')),
    FECHA TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    ID_COMPRA_G2 NUMBER,
    CONSTRAINT UQ_SOL_COMPRA UNIQUE (ID_COMPRA_G2)
);

CREATE TABLE SOL_ENTREGA_PARTIDA (
    ID_SOLICITUD NUMBER NOT NULL,
    NUMERO NUMBER NOT NULL,
    COLOR VARCHAR2(5) NOT NULL CHECK (COLOR IN ('ROJO','VERDE')),
    PESO_CRUDO NUMBER(15,3) NOT NULL CHECK (PESO_CRUDO > 0),
    PESO_ESTIMADO NUMBER(15,3) NOT NULL,
    CONSTRAINT CK_SOL_PESOS CHECK (PESO_ESTIMADO > 0 AND PESO_ESTIMADO <= PESO_CRUDO),
    PRIMARY KEY (ID_SOLICITUD, NUMERO)
);

