-- -----------------------------------------------------------------------------
-- 6. RECALCULO DE ESTADISTICAS DEL OPTIMIZADOR ORACLE CBO
-- -----------------------------------------------------------------------------
PROMPT [6/6] Recalculando estadisticas del optimizador CBO...
BEGIN
   DBMS_STATS.GATHER_SCHEMA_STATS(ownname => USER, estimate_percent => 100, cascade => TRUE);
END;
/

PROMPT =============================================================================
PROMPT RESUMEN DE EVIDENCIA: LOS 5 TIPOS DE PARTICIONAMIENTO ACTIVOS EN SITRA-ORO
PROMPT =============================================================================
SET LINESIZE 200 PAGESIZE 50;
COL TABLA FORMAT A20;
COL TIPO_PRIMARIO FORMAT A14;
COL SUBPARTICION FORMAT A14;
COL INTERVALO_AUTO FORMAT A28;
COL CANT_PARTICIONES FORMAT 9999;

SELECT table_name AS TABLA,
       partitioning_type AS TIPO_PRIMARIO,
       subpartitioning_type AS SUBPARTICION,
       interval AS INTERVALO_AUTO,
       partition_count AS CANT_PARTICIONES
FROM user_part_tables
ORDER BY table_name;

PROMPT =============================================================================
PROMPT DETALLE DE PARTICIONES FISICAS Y FILAS (USER_TAB_PARTITIONS)
PROMPT =============================================================================
COL PARTICION FORMAT A20;
COL POS FORMAT 99;
COL FILAS FORMAT 9999;
COL LIMITE FORMAT A32;

SELECT table_name AS TABLA, partition_name AS PARTICION, partition_position AS POS, 
       num_rows AS FILAS, high_value AS LIMITE
FROM user_tab_partitions
WHERE table_name IN ('TRANSACCIONES_G2', 'CENTROS_ACOPIO', 'MINEROS', 'LIQUIDACIONES_G1', 'COMPRAS_G2')
ORDER BY table_name, partition_position;

PROMPT INSTALACION EXITOSA: Las 22 tablas y los 5 tipos de particionamiento estan operativos.

-- ============================================================================
-- S14: TABLA DE AUDITORÍA DE ACCIONES CRÍTICAS (LP2 - UNIDAD 3)
-- ============================================================================
CREATE TABLE AUDITORIA (
    ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ACTOR VARCHAR2(100),
    ACCION VARCHAR2(50) NOT NULL,
    ENTIDAD VARCHAR2(50) NOT NULL,
    ENTIDAD_ID NUMBER,
    FECHA TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    DETALLE VARCHAR2(500)
);

GRANT SELECT, INSERT, UPDATE, DELETE ON AUDITORIA TO BOMERP_APP;
